void check(bool b,const char*m){if(!b)throw std::runtime_error(m);}
template<class F>void rejects(F f){bool bad=false;try{f();}catch(...){bad=true;}check(bad,"Expected image rejection");}
void put(std::vector<uint8_t>&b,size_t at,uint32_t n){for(int k=0;k<4;++k)b[at+k]=uint8_t(n>>(8*k));}
std::vector<uint8_t> compressed(uint32_t fourcc){auto b=encode_dds({4,4,std::vector<uint8_t>(64)});b.resize(128+(fourcc==0x31545844?8:16));put(b,80,4);put(b,84,fourcc);put(b,88,0);put(b,92,0);put(b,96,0);put(b,100,0);put(b,104,0);return b;}
void write(const std::filesystem::path&p,const std::vector<uint8_t>&b){std::ofstream f(p,std::ios::binary);f.write(reinterpret_cast<const char*>(b.data()),b.size());}
